import AdmZip = require('adm-zip');
const MAX_FILES = 10000;
const MAX_SIZE = 1000000000;
const THRESHOLD_RATIO = 10;
let fileCount = 0;
let totalSize = 0;
const zip = new AdmZip('./foo.zip');
for (const entry of zip.getEntries()) {
  fileCount++;
  if (fileCount > MAX_FILES) throw new Error('Reached max. number of files');
  const entrySize = entry.getData().length;
  totalSize += entrySize;
  if (totalSize > MAX_SIZE) throw new Error('Reached max. size');
  if (entry.header.compressedSize > 0 && entrySize / entry.header.compressedSize > THRESHOLD_RATIO) throw new Error('Reached max. compression ratio');
  if (!entry.isDirectory) zip.extractEntryTo(entry.entryName, '.', false, false);
}

